```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>

using namespace std;

int main() {
    // Dateiname und Suchwort einlesen
    string filename;
    string search_word;
    cout << "Bitte geben Sie den Dateinamen ein: ";
    cin >> filename;
    cout << "Bitte geben Sie das Suchwort ein: ";
    cin >> search_word;

    // Map zum Speichern der Anzahl der Vorkommen des Suchworts
    map<string, int> word_count;

    // Datei öffnen
    ifstream file(filename);
    if (!file) {
        cout << "Fehler: Datei konnte nicht geöffnet werden." << endl;
        return 1;
    }

    // Zeile für Zeile lesen und Suchwort zählen
    string line;
    while (getline(file, line)) {
        // Wörter in der Zeile finden und zählen
        size_t pos = 0;
        string token;
        while ((pos = line.find(" ")) != string::npos) {
            token = line.substr(pos, pos + 1);
            line.erase(pos, pos + 1);

            // Suchwort zählen
            if (search_word == token) {
                word_count[search_word]++;
            }
        }
        // Letztes Wort zählen
        if (!line.empty()) {
            if (search_word == line) {
                word_count[search_word]++;
            }
        }
    }

    // Ergebnis ausgeben
    if (word_count.empty()) {
        cout << "Das Suchwort '" << search_word << "' wurde nicht gefunden." << endl;
    } else {
        cout << "Das Suchwort '" << search_word << "' kommt " << word_count[search_word] << " mal vor." << endl;
    }

    file.close();
    return 0;
}
```

